class Solution:
    def maximumDistance(self, words: List[str]) -> int:
        n = len(words)
        if words[0] != words[-1]:
            return n
        i = 0
        while i < n and words[i] == words[0]:
            i += 1
        if i == n:
            return 0
        j = n - 1
        while words[j] == words[-1]:
            j -= 1
        return max(j + 1, n - i)

