class Solution {
public:
    int maximumDistance(vector<string>& words) {
        int n = words.size();
        if (words[0] != words[n-1]) return n;
        int i = 0;
        while (i < n && words[i] == words[0]) i++;
        if (i == n) return 0;
        int j = n - 1;
        while (words[j] == words[n-1]) j--;
        return max(j + 1, n - i);
    }
};

